### 1. Service interface: `apps/server/src/persistence/Services/ConversationSearch.ts`

Follow the exact pattern from `ProjectionThreadMessages.ts` (service file):

```typescript
import { MessageId, ThreadId, ProjectId, IsoDateTime } from "@t3tools/contracts";
import { Schema, ServiceMap } from "effect";
import type { Effect } from "effect";
import type { ProjectionRepositoryError } from "../Errors.ts";

export const ConversationSearchMatchRow = Schema.Struct({
  threadId: ThreadId,
  threadTitle: Schema.String,
  messageId: Schema.NullOr(MessageId),
  snippet: Schema.String,
  relevance: Schema.Number,
  threadCreatedAt: IsoDateTime,
  threadUpdatedAt: IsoDateTime,
});
export type ConversationSearchMatchRow = typeof ConversationSearchMatchRow.Type;

export const SearchAllInput = Schema.Struct({
  query: Schema.String,
  projectId: ProjectId,
  limit: Schema.optional(Schema.Number),
  filter: Schema.optional(Schema.Literals(["all", "active", "archived"])),
});
export type SearchAllInput = typeof SearchAllInput.Type;

export interface ConversationSearchRepositoryShape {
  readonly searchAll: (
    input: SearchAllInput,
  ) => Effect.Effect<ReadonlyArray<ConversationSearchMatchRow>, ProjectionRepositoryError>;

  readonly indexMessage: (
    input: { threadId: string; messageId: string; role: string; text: string; rowid: number },
  ) => Effect.Effect<void, ProjectionRepositoryError>;

  readonly updateThreadTitle: (
    input: { threadId: string; title: string; rowid: number },
  ) => Effect.Effect<void, ProjectionRepositoryError>;

  readonly removeThread: (
    input: { threadId: string },
  ) => Effect.Effect<void, ProjectionRepositoryError>;
}

export class ConversationSearchRepository extends ServiceMap.Service<
  ConversationSearchRepository,
  ConversationSearchRepositoryShape
>()("t3/persistence/Services/ConversationSearch/ConversationSearchRepository") {}
```

### 2. Layer implementation: `apps/server/src/persistence/Layers/ConversationSearch.ts`

Follow the exact pattern from `ProjectionThreadMessages.ts` (layer file):

```typescript
import * as SqlClient from "effect/unstable/sql/SqlClient";
import { Effect, Layer } from "effect";
import { toPersistenceSqlError } from "../Errors.ts";
import {
  ConversationSearchRepository,
  type ConversationSearchRepositoryShape,
} from "../Services/ConversationSearch.ts";

const makeConversationSearchRepository = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;

  const searchAll: ConversationSearchRepositoryShape["searchAll"] = (input) => {
    const limit = input.limit ?? 20;
    const filter = input.filter ?? "all";

    // Build the query: search both messages FTS and threads FTS, 
    // join with projection_threads for metadata, group by thread
    // Use FTS5 snippet() for highlighted excerpts and bm25() for ranking
    return sql.unsafe(`
      WITH message_hits AS (
        SELECT
          fts.thread_id,
          fts.message_id,
          snippet(projection_messages_fts, 3, '<mark>', '</mark>', '...', 40) AS snippet,
          bm25(projection_messages_fts) AS relevance
        FROM projection_messages_fts AS fts
        WHERE projection_messages_fts MATCH ${sql.literal("$1")}
        ORDER BY relevance
        LIMIT ${sql.literal("$2")}
      ),
      title_hits AS (
        SELECT
          fts.thread_id,
          NULL AS message_id,
          snippet(projection_threads_fts, 1, '<mark>', '</mark>', '...', 40) AS snippet,
          bm25(projection_threads_fts) AS relevance
        FROM projection_threads_fts AS fts
        WHERE projection_threads_fts MATCH ${sql.literal("$3")}
        ORDER BY relevance
        LIMIT ${sql.literal("$4")}
      ),
      all_hits AS (
        SELECT * FROM message_hits
        UNION ALL
        SELECT * FROM title_hits
      )
      SELECT
        h.thread_id AS "threadId",
        t.title AS "threadTitle",
        h.message_id AS "messageId",
        h.snippet,
        h.relevance,
        t.created_at AS "threadCreatedAt",
        t.updated_at AS "threadUpdatedAt"
      FROM all_hits h
      JOIN projection_threads t ON t.thread_id = h.thread_id
      WHERE t.project_id = ${sql.literal("$5")}
        AND t.deleted_at IS NULL
        ${filter === "active" ? "AND t.archived_at IS NULL" : ""}
        ${filter === "archived" ? "AND t.archived_at IS NOT NULL" : ""}
      ORDER BY h.relevance
      LIMIT ${sql.literal("$6")}
    `, [input.query, limit, input.query, limit, input.projectId, limit]).pipe(
      Effect.mapError(toPersistenceSqlError("ConversationSearchRepository.searchAll:query")),
    );
  };
  // ... etc
});
```

**IMPORTANT**: The above is pseudocode. The actual implementation must use the `sql` tagged template literal from `SqlClient.SqlClient` properly. Looking at how other repos work, you should use parameterized queries via the sql template tag. FTS5 MATCH queries use special syntax — the query string should be properly escaped.

Here's a cleaner approach for `searchAll`:

```typescript
const searchAll: ConversationSearchRepositoryShape["searchAll"] = (input) => {
  const limit = input.limit ?? 20;
  const filter = input.filter ?? "all";

  // Escape FTS5 query: wrap terms in double quotes to prevent syntax errors
  const ftsQuery = input.query
    .replace(/"/g, '""')
    .split(/\s+/)
    .filter(Boolean)
    .map(term => `"${term}"`)
    .join(' ');

  if (ftsQuery.length === 0) {
    return Effect.succeed([]);
  }

  // Use raw SQL since FTS5 MATCH requires special syntax
  // Build filter clause
  const filterClause = 
    filter === "active" ? "AND t.archived_at IS NULL" :
    filter === "archived" ? "AND t.archived_at IS NOT NULL" : "";

  return Effect.tryPromise({
    try: () => sql.unsafe(`
      WITH message_hits AS (
        SELECT
          fts.thread_id,
          fts.message_id,
          snippet(projection_messages_fts, 3, '<mark>', '</mark>', '...', 40) AS snippet,
          bm25(projection_messages_fts) AS relevance
        FROM projection_messages_fts AS fts
        WHERE projection_messages_fts MATCH '${ftsQuery}'
        LIMIT ${limit * 3}
      ),
      title_hits AS (
        SELECT
          fts.thread_id,
          NULL AS message_id,
          snippet(projection_threads_fts, 1, '<mark>', '</mark>', '...', 40) AS snippet,
          bm25(projection_threads_fts) AS relevance
        FROM projection_threads_fts AS fts
        WHERE projection_threads_fts MATCH '${ftsQuery}'
        LIMIT ${limit}
      ),
      all_hits AS (
        SELECT * FROM message_hits
        UNION ALL
        SELECT * FROM title_hits
      )
      SELECT
        h.thread_id AS "threadId",
        t.title AS "threadTitle",
        h.message_id AS "messageId",
        h.snippet,
        h.relevance,
        t.created_at AS "threadCreatedAt",
        t.updated_at AS "threadUpdatedAt"
      FROM all_hits h
      JOIN projection_threads t ON t.thread_id = h.thread_id
      WHERE t.project_id = '${input.projectId}'
        AND t.deleted_at IS NULL
        ${filterClause}
      ORDER BY h.relevance
      LIMIT ${limit}
    `),
    catch: (error) => toPersistenceSqlError("ConversationSearchRepository.searchAll:query")(error as any),
  });
};
```

Actually, you should use the Effect/SQL client properly. Look at how `sql` tagged template works in the codebase — it supports parameterized queries. However, FTS5 MATCH syntax may not work well with parameter binding. Use `sql.unsafe()` with manually escaped parameters for the FTS query, and the standard `sql` template for regular queries.

